export const QUIZ_ITEMS = [
  { id: "2465", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما الفرق بين اسمَي الله «الغفور» و«الغفّار»؟", answer: "الغفور: يدل على سعة المغفرة في ذاتها مهما عظمت الذنوب. الغفّار: يدل على كثرة المغفرة وتكرارها مراراً وتكراراً، أي كثير المغفرة لا ينضب عفوه. والاسمان معاً يُعطيان المؤمن رجاءً بسعة المغفرة واستمرارها مهما كان العبد مذنباً وكثُرت عودته بالتوبة.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2466", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "سهل", question: "ما معنى اسم الله «الحليم» وكيف يُفرَّق بينه وبين الصبور؟", answer: "الحليم: الذي لا يستفزه عصيان العصاة ولا يُقلقه انتشار المعاصي، فيؤخر العقوبة رحمةً وحكمةً. الصبور في المقابل: يركز على التأخير الطويل مع الإحاطة بالخلق. الحليم يُشير إلى الطمأنينة التامة وعدم تغيّر حال الله بمعصية عبده.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2467", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما معنى اسمَي الله «الوكيل» و«الكفيل»؟", answer: "الوكيل: الذي يتولى مصالح عباده ويكفيهم ما يهمهم. قال تعالى: ﴿وَكَفَىٰ بِاللَّهِ وَكِيلاً﴾. ومعناه التفويض التام إليه والاعتماد عليه وحده في جلب المصالح ودرء المفاسد. وهو ضمنياً يتضمن الكفالة والرعاية الكاملة لمن توكل عليه.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2468", section: "الأسماء الحسنى", category: "الأسماء الحسنى عموماً", level: "سهل", question: "كم اسماً من أسماء الله الحسنى وردت في الحديث المشهور عند الترمذي وابن ماجه؟", answer: "تسعة وتسعون اسماً في حديث: «إن لله تسعة وتسعين اسماً مئةً إلا واحداً من أحصاها دخل الجنة» (البخاري ومسلم). غير أن العلماء اختلفوا في تعداد تلك الأسماء لأن الحديث في الصحيحين لم يذكرها، بل ذِكرها في رواية الترمذي من زيادة راوٍ يناقشها العلماء.", explanation: "يُستفاد منه في باب الأسماء الحسنى عموماً. يُستفاد منه في باب الأسماء الحسنى عموماً مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2469", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "ما معنى اسم الله «الغفار» و«الغفور»؟ وما الفرق بينهما؟", answer: "الغفور: صيغة مبالغة تدل على عِظَم المغفرة وشمولها — أي أنه يغفر الذنب العظيم. الغفار: صيغة مبالغة تدل على تكرار المغفرة ودوامها — أي أنه يغفر مرة بعد مرة. فالغفور يشير إلى الكمية والعِظَم، والغفار يشير إلى التكرار والاستمرار. قال تعالى: ﴿إِنَّهُ كَانَ غَفَّاراً﴾ (نوح: 10) وقال: ﴿وَهُوَ الْغَفُورُ الرَّحِيمُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2470", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما معنى اسم الله «القيوم»؟ وما دلالته الاعتقادية؟", answer: "القيوم: من قام يقوم — صيغة مبالغة تجمع معنيين: 1) القائم بنفسه: أي الغني عن كل شيء الذي لا يحتاج لأحد في وجوده. 2) المُقيم لغيره: أي الذي يقوم على كل مخلوق فيحفظه ويرزقه ويُدبّره. الدلالة الاعتقادية: استقلال الله التام عن خلقه، وحاجة المخلوقات جميعاً إليه. ولذا جُمع مع «الحي» في آية الكرسي: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2471", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "كم عدد أسماء الله الحسنى المذكورة في الحديث النبوي الشريف؟", answer: "تسعة وتسعون (99) اسماً، وردت في حديث أبي هريرة أن النبي ﷺ قال: «إن لله تسعة وتسعين اسماً من أحصاها دخل الجنة»، والمقصود بـ«الإحصاء» معرفتها وحفظها والتعبد لله بمعانيها.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2472", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "ما معنى اسم الله «الرحمن» لغةً واصطلاحاً؟", answer: "الرحمن مشتق من الرحمة، وهو من أبنية المبالغة على وزن فَعْلان مما يدل على السعة والامتلاء، أي ذو الرحمة الواسعة الشاملة لجميع الخلق في الدنيا. واسم الرحمن خاص بالله لا يُطلق على غيره، بخلاف الرحيم الذي وُصف به بعض الناس.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2473", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما الفرق بين اسمَي الله «العزيز» و«القوي»؟", answer: "العزيز: ذو العزة الكاملة، غير المغلوب، الذي يعتز به كل شيء ويحتاج إليه كل شيء. القوي: ذو القوة التامة التي لا تنقص ولا تعتريها غلبة. العزة تتضمن معنى الامتناع وعدم الانكسار، بينما القوة تتضمن الاقتدار والمَكنة.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2474", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما اسم الله الذي يدل على أنه الوحيد المستحق للعبادة؟", answer: "اسم «الإله» أو «الله» بالعلمية. أما في أسماء الله الحسنى: «الواحد» و«الأحد» يدلان على انفراده بالوحدانية. الواحد: المنفرد الذي لا نظير له. الأحد: المنفرد الذي لا يقبل الانقسام ولا الشركة في أي وجه.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2475", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "صعب", question: "ما الفرق بين «الحكيم» و«العليم» من أسماء الله الحسنى؟", answer: "العليم: ذو العلم الشامل بكل شيء ظاهراً وباطناً، ماضياً وحاضراً ومستقبلاً، لا يخفى عليه مثقال ذرة. الحكيم: ذو الحكمة في كل أفعاله وأقواله وأقداره، بمعنى إتقان الأشياء وإحكامها ووضعها في مواضعها اللائقة. فالعلم يتعلق بالمعرفة، والحكمة بحُسن التصرف.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2476", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "صعب", question: "من العلماء الذين ألّفوا كتباً مستقلة في شرح أسماء الله الحسنى؟", answer: "أبرز من ألّف في الأسماء الحسنى: ابن القيم في «مدارج السالكين» وكتابه المستقل «شفاء العليل» وبدائع الفوائد. والبيهقي في «الأسماء والصفات». وابن منده في «التوحيد». والرازي في «لوامع البينات». وفي المعاصرين سعيد حوّى في «الأساس في السنة».", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2477", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من مؤسس المذهب الحنفي؟", answer: "أبو حنيفة النعمان — الإمام الأعظم مؤسس المذهب الحنفي، من أهل الكوفة (ت 150هـ).", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2478", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من مؤسس المذهب المالكي؟", answer: "مالك بن أنس — إمام دار الهجرة ومؤسس المذهب المالكي، صاحب الموطأ (ت 179هـ).", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2479", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من مؤسس المذهب الشافعي؟", answer: "محمد بن إدريس الشافعي — مؤسس المذهب الشافعي وواضع أصول الفقه بكتاب الرسالة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2480", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من مؤسس المذهب الحنبلي؟", answer: "أحمد بن حنبل — إمام أهل السنة ومؤسس المذهب الحنبلي، صبر في فتنة خلق القرآن.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2481", section: "الصالحون", category: "الحديث", level: "متوسط", question: "من صاحب صحيح البخاري؟", answer: "محمد بن إسماعيل البخاري — صاحب أصح كتاب بعد كتاب الله، صحيح البخاري (ت 256هـ).", explanation: "يُستفاد منه في باب الحديث. يُستفاد منه في باب الحديث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2482", section: "الصالحون", category: "الحديث", level: "متوسط", question: "من صاحب صحيح مسلم؟", answer: "مسلم بن الحجاج — صاحب صحيح مسلم، من أئمة الحديث في نيسابور (ت 261هـ).", explanation: "يُستفاد منه في باب الحديث. يُستفاد منه في باب الحديث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2483", section: "الصالحون", category: "الفقه", level: "متوسط", question: "من الإمام المعروف بإمام دار الهجرة؟", answer: "مالك بن أنس — الإمام المعروف بإمام دار الهجرة، مؤسس المذهب المالكي في المدينة.", explanation: "يُستفاد منه في باب الفقه. يُستفاد منه في باب الفقه مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2484", section: "الصالحون", category: "التفسير", level: "متوسط", question: "من الصحابي المشهور بتفسير القرآن؟", answer: "عبد الله بن عباس رضي الله عنهما — حبر الأمة وترجمان القرآن، أشهر الصحابة في التفسير.", explanation: "يُستفاد منه في باب التفسير. يُستفاد منه في باب التفسير مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2485", section: "الصالحون", category: "الزهد", level: "متوسط", question: "من التابعي المشهور من أهل البصرة بالزهد والموعظة؟", answer: "الحسن البصري — التابعي المشهور من أهل البصرة بالزهد والموعظة والعلم (ت 110هـ).", explanation: "يُستفاد منه في باب الزهد. يُستفاد منه في باب الزهد مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2486", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من الإمام صاحب كتاب الموطأ؟", answer: "مالك بن أنس — الإمام صاحب كتاب الموطأ، أول كتاب حديثي جامع على الأبواب الفقهية.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2487", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من صاحب كتاب إحياء علوم الدين؟", answer: "أبو حامد الغزالي — صاحب كتاب إحياء علوم الدين، حجة الإسلام (ت 505هـ).", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2488", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من العالم الحنبلي الملقب بشيخ الإسلام الذي جُمعت فتاواه ورسائله في «مجموع الفتاوى»؟", answer: "أحمد بن عبد الحليم بن تيمية الحرّاني (٦٦١-٧٢٨هـ). و«مجموع الفتاوى» ليس كتابًا صنّفه بنفسه، وإنما هو جمعٌ لرسائله وفتاواه قام به الشيخ عبد الرحمن بن قاسم النجدي وابنه محمد بعد قرون من وفاته. ولقب «شيخ الإسلام» أُطلق على غيره من العلماء أيضًا", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2489", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من صاحب كتاب زاد المعاد ومدارج السالكين؟", answer: "محمد بن أبي بكر الزُّرَعي ثم الدمشقي، المعروف بابن قيِّم الجوزية (٦٩١-٧٥١هـ)، تلميذ ابن تيمية. ونسبته إلى أن أباه كان قيِّمًا على المدرسة الجوزية بدمشق، فالصواب في اسمه «ابن قيِّم الجوزية» لا «ابن قيم الجوزية»", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2490", section: "الصالحون", category: "التفسير", level: "متوسط", question: "من صاحب تفسير جامع البيان المعروف بتفسير الطبري؟", answer: "محمد بن جرير الطبري (٢٢٤-٣١٠هـ)، واسم تفسيره كاملًا «جامع البيان عن تأويل آي القرآن»", explanation: "يُستفاد منه في باب التفسير. يُستفاد منه في باب التفسير مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2491", section: "الصالحون", category: "التفسير", level: "متوسط", question: "من صاحب التفسير المشهور بـ (تفسير ابن كثير)؟", answer: "إسماعيل بن عمر بن كثير القرشي الدمشقي (٧٠٠-٧٧٤هـ)، واسم كتابه «تفسير القرآن العظيم»", explanation: "يُستفاد منه في باب التفسير. يُستفاد منه في باب التفسير مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2492", section: "الصالحون", category: "الفقه", level: "متوسط", question: "من أول من صنّف في أصول الفقه بكتاب الرسالة؟", answer: "الإمام الشافعي — أول من صنّف في أصول الفقه بكتاب الرسالة المعروف.", explanation: "يُستفاد منه في باب الفقه. يُستفاد منه في باب الفقه مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2493", section: "الصالحون", category: "الحديث", level: "صعب", question: "من الأئمة الذين لُقِّبوا بـ«أمير المؤمنين في الحديث»؟", answer: "لقبٌ أُطلق على جماعة من كبار الحفاظ لا على واحد بعينه، منهم شعبة بن الحجاج وسفيان الثوري وعبد الله بن المبارك وأحمد بن حنبل والبخاري والدارقطني؛ وأشهر من ينصرف إليه اللقب عند الإطلاق: الإمام البخاري", explanation: "يُستفاد منه في باب الحديث. يُستفاد منه في باب الحديث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2494", section: "الصالحون", category: "العلماء", level: "صعب", question: "من الإمام الذي وُلد عام 150هـ وعدّه كثير من العلماء مجدد القرن الثاني؟", answer: "الإمام محمد بن إدريس الشافعي (١٥٠-٢٠٤هـ)، وُلد سنة وفاة أبي حنيفة. وعدّه جماعة من العلماء مجدّد رأس المئة الثانية، وقيل بل هو الإمام أحمد بن حنبل؛ والمسألة اجتهادية في تنزيل حديث «إن الله يبعث لهذه الأمة على رأس كل مئة سنة من يجدد لها دينها» (أخرجه أبو داود ٤٢٩١)", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2495", section: "الصالحون", category: "العلماء", level: "متوسط", question: "من صاحب رياض الصالحين؟", answer: "يحيى بن شرف النووي — صاحب رياض الصالحين وأربعين نووية (ت 676هـ).", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2496", section: "الصالحون", category: "العلماء", level: "صعب", question: "من الإمام صاحب «الجامع» المعروف بسنن الترمذي؟", answer: "محمد بن عيسى بن سَوْرة الترمذي (٢٠٩-٢٧٩هـ). واسم كتابه «الجامع» أو «السنن»، ويُسمّى «الجامع الكبير»؛ وأما تسميته «الجامع الصحيح» فتسمية متأخرة غير دقيقة، لأنه جمع فيه الصحيح والحسن والضعيف وبيّن درجة كثير من أحاديثه", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2497", section: "الحديث", category: "المصطلح", level: "سهل", question: "ما الحديث الذي يُعدّ من جوامع كلمه ﷺ ويبدأ بـ (إنما الأعمال)؟", answer: "«إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى» — رواه البخاري (1) ومسلم (1907) عن عمر بن الخطاب رضي الله عنه", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2498", section: "الحديث", category: "الكتب", level: "سهل", question: "ما الكتاب الذي يأتي في المرتبة الثانية بعد صحيح البخاري في الصحة؟", answer: "صحيح مسلم — وهو الثاني بعد صحيح البخاري في الصحة عند جمهور العلماء؛ وذهب أبو علي النيسابوري وبعض علماء المغرب إلى تفضيل صحيح مسلم، ومرادهم حسن السياق وجمع طرق الحديث في موضع واحد لا رجحان أصل الصحة", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2499", section: "الحديث", category: "الكتب", level: "متوسط", question: "ما الكتب الستة (الأصول الستة) في الحديث النبوي؟", answer: "صحيح البخاري، وصحيح مسلم، وسنن أبي داود، وجامع الترمذي، وسنن النسائي، وسنن ابن ماجه. وتسميتها «الصحاح الستة» تسامح شائع؛ فالحكم بالصحة على الإطلاق إنما هو للصحيحين، أما السنن الأربعة ففيها الصحيح والحسن والضعيف، ولهذا يسميها المحدثون «الكتب الستة» أو «الأصول الستة»", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2500", section: "الحديث", category: "الكتب", level: "متوسط", question: "من ألّف مسند الإمام أحمد؟", answer: "الإمام أحمد بن حنبل رحمه الله جمعه وانتقاه؛ ورواه عنه ابنه عبد الله وزاد فيه زيادات، ثم رواه عن عبد الله أبو بكر القطيعي وله فيه زيادات أيضًا — فليس كل ما في المطبوع من رواية الإمام أحمد نفسه", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2501", section: "الحديث", category: "الكتب", level: "متوسط", question: "ما الكتاب الأول المصنَّف في الحديث النبوي الجامع بين الفقه والحديث؟", answer: "الموطأ لمالك بن أنس — أول كتاب مصنَّف في الحديث النبوي جامع بين الفقه والرواية.", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2502", section: "الحديث", category: "المصطلح", level: "متوسط", question: "ما الحديث القدسي؟", answer: "ما أضافه النبي ﷺ إلى ربه عز وجل مما أوحي إليه من غير القرآن، فيرويه عن ربه. وهل لفظه من الله أم المعنى من الله واللفظ من النبي ﷺ؟ مسألة خلافية بين أهل العلم والقولان مشهوران. ويفارق القرآنَ بأنه لا يُتعبَّد بتلاوته، ولا تصح به الصلاة، ولا يلزم فيه التواتر، وفيه الصحيح والضعيف", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2503", section: "الحديث", category: "الرواة", level: "متوسط", question: "من الصحابي الذي روى أكثر من أربعة آلاف حديث؟", answer: "أبو هريرة رضي الله عنه — الصحابي الذي روى أكثر من أربعة آلاف حديث عن النبي ﷺ.", explanation: "يُستفاد منه في باب الرواة. يُستفاد منه في باب الرواة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2504", section: "الحديث", category: "الرواة", level: "متوسط", question: "من أول من أمر بتدوين الحديث رسمياً من الخلفاء؟", answer: "عمر بن عبد العزيز رحمه الله؛ كتب إلى أبي بكر بن محمد بن حزم: «انظر ما كان من حديث رسول الله ﷺ فاكتبه، فإني خفت دروس العلم وذهاب العلماء» — علّقه البخاري في كتاب العلم. وأشهر من قام بالتدوين بأمره: محمد بن مسلم بن شهاب الزهري", explanation: "يُستفاد منه في باب الرواة. يُستفاد منه في باب الرواة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2505", section: "الحديث", category: "الأحاديث الجامعة", level: "متوسط", question: "ما الحديث الذي يُعدّ من جوامع كلمه ويبدأ بـ (من حسن إسلام المرء)؟", answer: "«من حسن إسلام المرء تركه ما لا يعنيه» — رواه الترمذي (2317) وابن ماجه، وهو الحديث الثاني عشر من الأربعين النووية، وحسّنه النووي", explanation: "يُستفاد منه في باب الأحاديث الجامعة. يُستفاد منه في باب الأحاديث الجامعة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2506", section: "الحديث", category: "الأحاديث الجامعة", level: "متوسط", question: "ما أثقل شيء في الميزان يوم القيامة كما جاء في الحديث؟", answer: "حسن الخلق؛ لقوله ﷺ: «ما من شيء أثقل في ميزان المؤمن يوم القيامة من خلق حسن» — رواه أبو داود (4799) والترمذي (2002) عن أبي الدرداء رضي الله عنه، وصححه الألباني", explanation: "يُستفاد منه في باب الأحاديث الجامعة. يُستفاد منه في باب الأحاديث الجامعة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2507", section: "الحديث", category: "الأحاديث الجامعة", level: "سهل", question: "أكمل الحديث: لا يؤمن أحدكم حتى يحب لأخيه...", answer: "«ما يحب لنفسه» — متفق عليه: البخاري (13) ومسلم (45) عن أنس بن مالك رضي الله عنه", explanation: "يُستفاد منه في باب الأحاديث الجامعة. يُستفاد منه في باب الأحاديث الجامعة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2508", section: "الحديث", category: "الأربعون النووية", level: "متوسط", question: "من جمع الأربعين النووية في الحديث النبوي؟", answer: "يحيى بن شرف النووي — الإمام الذي جمع الأربعين النووية في الحديث (ت 676هـ).", explanation: "يُستفاد منه في باب الأربعون النووية. يُستفاد منه في باب الأربعون النووية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2509", section: "الحديث", category: "الصحاح", level: "متوسط", question: "ما الكتب الستة في الحديث؟", answer: "صحيح البخاري، وصحيح مسلم، وسنن أبي داود، وجامع الترمذي، وسنن النسائي، وسنن ابن ماجه. وتسميتها «الصحاح الستة» تسامح شائع لا يصح اصطلاحاً؛ فالصحيح المحض منها الصحيحان، وأمّا السنن الأربعة ففيها الصحيح والحسن والضعيف. والسادس منها سنن ابن ماجه عند ابن طاهر المقدسي، وجعل بعضهم مكانه موطأ مالك", explanation: "يُستفاد منه في باب الصحاح. يُستفاد منه في باب الصحاح مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2510", section: "الحديث", category: "المصطلح", level: "متوسط", question: "ما الحديث الحسن؟", answer: "ما اتصل سنده بنقل عدلٍ خفيفِ الضبط عن مثله إلى منتهاه، من غير شذوذ ولا علة؛ فهو كالصحيح في شروطه إلا أن راويه أخفُّ ضبطاً. وينقسم إلى حسن لذاته، وحسن لغيره وهو الضعيف الذي تعددت طرقه فجبر بعضها بعضاً", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2511", section: "الحديث", category: "المصطلح", level: "صعب", question: "ما الإسناد؟", answer: "سلسلة الرجال الموصِّلة إلى المتن؛ وقد ينتهي إلى النبي ﷺ فيكون الحديث مرفوعاً، أو إلى صحابي فيكون موقوفاً، أو إلى تابعي فيكون مقطوعاً. وبه تُعرف صحة الرواية من ضعفها؛ قال عبد الله بن المبارك: «الإسناد من الدين، ولولا الإسناد لقال من شاء ما شاء» (رواه مسلم في مقدمة صحيحه)", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2512", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما تعريف الحديث الصحيح؟", answer: "ما اتصل سنده بنقل العدل الضابط عن مثله إلى منتهاه، وسلم من الشذوذ والعلة", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2513", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما تعريف الحديث الحسن وكيف يختلف عن الصحيح؟", answer: "الحسن ما اتصل سنده ورواته عدول لكن خفيف الضبط، وهو دون الصحيح في المرتبة ويُحتج به", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2514", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما الحديث الضعيف وما حكم العمل به؟", answer: "ما فقد شرطاً فأكثر من شروط القبول (الصحيح أو الحسن). ومنهج هذا الموقع: لا يُعمل بالضعيف في الأحكام ولا العقائد ولا الترغيب ولا التعبّد؛ والخلاف التاريخي في فضائل الأعمال يُذكر للعلم مع ترجيح الترك والاستغناء بالصحيح والحسن", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" }
];

