export const FAWAID_ITEMS = [
  { text: "إن الله مع الصابرين — هذه المعية تعني النصر والتأييد والحفظ والتوفيق، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما دلّ عليه الكتاب والسنة.", category: "العقيدة", source: "البقرة: 153، وتفسير ابن سعدي", author_name: "الإمام ابن سعدي" },
  { text: "المجتمع المسلم كالجسد الواحد؛ إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة.", category: "الحديث", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "المؤمن للمؤمن كالبنيان يشد بعضه بعضاً — التماسك الاجتماعي فريضة إسلامية، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة.", category: "الحديث", source: "رواه البخاري ومسلم", author_name: "صحيح البخاري" },
  { text: "من كان في حاجة أخيه كان الله في حاجته، ومن فرّج كربة فرّج الله عنه كربة من كرب يوم القيامة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه البخاري ومسلم", author_name: "صحيح البخاري" },
  { text: "قل يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله — فالرحمة تسع كل ذنب، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما دلّ عليه الكتاب والسنة.", category: "العقيدة", source: "الزمر: 53", author_name: "القرآن الكريم" },
  { text: "التائب من الذنب كمن لا ذنب له — التوبة تمحو ما قبلها ولا تُبقي أثراً في سجل الأعمال، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما ثبت في السنة الصحيحة.", category: "العقيدة", source: "رواه ابن ماجه — حسنه الألباني", author_name: "سنن ابن ماجه" },
  { text: "نعمتان مغبون فيهما كثير من الناس: الصحة والفراغ — من عرف قدرهما ربح دنياه وآخرته، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة.", category: "الحديث", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "اغتنم خمساً قبل خمس: شبابك قبل هرمك، وصحتك قبل سقمك، وغناك قبل فقرك، وفراغك قبل شغلك، وحياتك قبل موتك. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه الحاكم في المستدرك (٧٨٤٦) عن ابن عباس وصححه على شرط الشيخين، والبيهقي في شعب الإيمان — صححه الألباني في صحيح الجامع وصحيح الترغيب", author_name: "المستدرك" },
  { text: "ألا بذكر الله تطمئن القلوب — الذكر دواء القلوب وغذاؤها وقوتها في كل وقت، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما دلّ عليه الكتاب والسنة.", category: "العقيدة", source: "الرعد: 28", author_name: "القرآن الكريم" },
  { text: "الذاكرون الله كثيراً والذاكرات أعد الله لهم مغفرة وأجراً عظيماً — فأكثر من الذكر في كل حال. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "الأحزاب: 35", author_name: "القرآن الكريم" },
  { text: "دعاء ذي النون في بطن الحوت: «لا إله إلا أنت سبحانك إني كنت من الظالمين» — استجاب الله له فنجّاه من الغمّ، وهي من أعظم أدعية الكرب. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الذكر والدعاء", source: "الأنبياء: 87", author_name: "القرآن الكريم" },
  { text: "الأمر بذكر الله ذكراً كثيراً والتسبيح بكرة وأصيلاً — لا يقتصر الذكر على وقت دون آخر بل يلازم المؤمن في كل أحواله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الذكر والدعاء", source: "الأحزاب: 41-42", author_name: "القرآن الكريم" },
  { text: "«فاذكروني أذكركم» — وعد إلهي مباشر: من ذكر الله في نفسه ذكره الله، ومن ذكره في ملأ ذكره الله في ملأ خير منه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الذكر والدعاء", source: "البقرة: 152", author_name: "القرآن الكريم" },
  { text: "«ادعوني أستجب لكم» — أمر إلهي بالدعاء مقروناً بوعد الإجابة، والاستكبار عن الدعاء استكبار عن العبادة نفسها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الذكر والدعاء", source: "غافر: 60", author_name: "القرآن الكريم" },
  { text: "من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت؛ فاللسان مفتاح الخير والشر، ومسؤولية المؤمن في كلامه عظيمة أمام الله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه؛ فالإيمان الحقيقي يُظهر نفسه في الإيثار والعدل مع إخوان المسلمين. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "إن الله كتب الإحسان على كل شيء؛ فإذا قتلتم فأحسنوا القتلة، وإذا ذبحتم فأحسنوا الذبح، وليحد أحدكم شفرته وليرح ذبيحته. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "من سلك طريقاً يلتمس فيه علماً سهّل الله له به طريقاً إلى الجنة؛ فطلب العلم عبادة وطريق نجاة لا مجرد جمع معلومات. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "خيركم من تعلّم القرآن وعلّمه؛ فالتعامل مع كتاب الله يستوجب تدبره وحفظه ونشره بين الناس بما ينفعهم. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "اقرأوا سورة البقرة؛ فإن أخذها بركة وتركها حسرة ولا تستطيعها البطلة؛ فالتمسك بكتاب الله حفظاً وعملاً من أعظم أسباب البركة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "ادعُ إلى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي أحسن؛ فالدعوة بالحسنى أبلغ في إقناع السامع وأقرب إلى قبول الحق. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الدعوة", source: "النحل: 125", author_name: "القرآن الكريم" },
  { text: "الهجرة انتقال للدعوة من الاضطهاد إلى بناء مجتمع مسلم؛ وهي من أعظم دروس الصبر والتخطيط في السيرة النبوية. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "السيرة النبوية — ابن هشام", author_name: "ابن هشام" },
  { text: "بدر أول معركة فاصلة؛ وفيها نصر الله المؤمنين، وبرهنت على أن النصر من عند الله لا من كثرة العدد والعدة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "صحيح البخاري — كتاب المغازي", author_name: "الإمام البخاري" },
  { text: "إن مع العسر يسراً — تكررت في سورة الشرح إشارة إلى أن العسر واحد واليسر اثنان؛ فلا ييأس المؤمن من رحمة الله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "الشرح: 5-6 — تفسير ابن كثير", author_name: "ابن كثير" },
  { text: "الاستعاذة قبل التلاوة سنة؛ لأن الشيطان يحاول صرف القارئ عن الخشوع، فالاستعاذة تحصنه من وسوسة الشيطان. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "«فإذا قرأت القرآن فاستعذ بالله من الشيطان الرجيم» — النحل: 98", author_name: "القرآن الكريم" }
];
